import type {Lesson,Topic} from './types';
const topic=(title:string,simple:string,why:string,mechanism:string,technical:string,experiment:string,source:string,steps:string[],remember:string,code?:string):Topic=>({title,simple,why,mechanism,technical,experiment,source,steps,remember,code});
const roots=['13_Drone_Attitude','14_Drone_Missions','15_Robot_Line_Follower','16_Robot_Navigation','17_Robot_Balancing','18_Robot_Competition','19_Final_Project'];
const src=(id:number,file:string)=>`${roots[id-13]}/${file}`;
export const applications:Lesson[]=[
{id:13,start:{"problem": "A gust tips a drone. Its program must estimate the tilt and choose motor changes that bring it back.", "outcome": "Explain the difference between true tilt and estimated tilt, then trace how the motor direction can restore or worsen it.", "firstExperiment": ["Leave Gain Kp at 4, Filter α at 0.98, Gust / initial roll at 20°, and Reverse mixer sign unchecked.", "Press Next several times; compare Truth °, Estimate ° and the four motor-command bars as the tilt changes.", "Check Reverse mixer sign, return to the first frame with Replay, and press Next again. Watch whether error grows and motors eventually switch off."]},shortTitle:'Keeping a drone level',subtitle:"Keep a drone level using measured motion and motor corrections.",prerequisites:[7,9,10],youKnow:["A sensor reading can differ from the actual motion.", "A repeated job can measure and correct at a chosen interval.", "Changing motor power changes motion."],adds:["Estimating left-right tilt from two sensors", "Choosing turning speed before motor correction", "Assigning four motors and enforcing safe output"],why:'A drone must correct a gust before a pilot can react. Seeing the loop explains both recovery and runaway.',topics:[
 topic("The real tilt and the measured tilt can differ","Imagine a gust lifting one side of a drone. Its actual tilt changes, but the program cannot see the aircraft directly. It receives numbers from sensors, estimates the tilt, and adjusts motor power. Here roll means leaning left or right; roll rate means how quickly that lean is changing.","Keeping actual tilt separate from measured tilt lets you see when a sensor mistake makes the program correct the wrong thing.","A gust changes the actual left-right tilt and the speed of rotation. Motion sensors report rotation speed and acceleration, with possible errors. The program uses those readings to estimate tilt. The controller compares estimated tilt with the desired level position. Different motor powers create a turning force, which changes the next tilt and sensor readings.",'Course world.c models a quadcopter on a gimbal using quaternions, rigid-body equations and 30 ms motor lag. World task: 500 Hz; control: 250 Hz. Our browser shows one roll axis with coarser steps. It is an educational simplification, not the original SITL.','Step the gust. Identify the first sensor change before looking at motor commands.',src(13,'world.c'),["A gust changes the actual left-right tilt and the speed of rotation.", "Motion sensors report rotation speed and acceleration, with possible errors.", "The program uses those readings to estimate tilt.", "The controller compares estimated tilt with the desired level position.", "Different motor powers create a turning force, which changes the next tilt and sensor readings."],"Actual tilt is what the body does; estimated tilt is what the program believes."),
 topic("Combine rotation speed with a clue from gravity","A gyroscope, or gyro, measures rotation speed. Multiply that speed by the time since the last reading to estimate how much the angle changed. An accelerometer measures forces associated with acceleration; when the drone is not accelerating strongly, its reading also gives a clue about the direction of gravity. Combining the two helps limit drift and shaking in the estimate.","A small constant gyro error builds up over time. A gravity correction can pull the estimate back, but vibration and movement can make that correction unreliable.","Start with the previous estimated angle. Multiply measured rotation speed by elapsed time and add the result to predict the next angle. Calculate another angle from the accelerometer reading. Use α, a number from 0 to 1, to choose the blend: more α means more gyro prediction. Feed the blended angle into the next correction; at α=1 no accelerometer correction remains.",'Complementary filter: angle = α × (previous angle + gyro × dt) + (1−α) × accelerometer angle. At α=1 correction disappears. Accelerometers measure specific force; translating acceleration is not separable from gravity by that sensor alone.','Compare α=0, 0.98 and 1. Watch estimate versus truth, not just whether motors move.',src(13,'control.c'),["Start with the previous estimated angle.", "Multiply measured rotation speed by elapsed time and add the result to predict the next angle.", "Calculate another angle from the accelerometer reading.", "Use α, a number from 0 to 1, to choose the blend: more α means more gyro prediction.", "Feed the blended angle into the next correction; at α=1 no accelerometer correction remains."],"Gyro predicts angle changes; the accelerometer supplies a gravity clue that can limit drift.",'s.roll  = a * (s.roll  + in->gyro[0] * CTRL_DT) + (1.0f - a) * s.roll_acc;'),
 topic("Choose a turning speed, then make the drone turn","Error means the difference between the desired value and the measured or estimated value. If the drone should be level but is tilted, the course controller first asks for a turning speed that would bring it back. A second controller adjusts motors to achieve that speed. A correction feeds back when the resulting motion is measured again.","Separating angle correction from speed correction helps handle motors that take time to respond. Excessive correction can push the drone past level and make it swing back and forth.","Subtract estimated angle from the desired angle to get angle error. Convert that angle error into a desired rotation speed. Subtract measured rotation speed from desired speed to get rate error. P (proportional) responds to current error; I (integral) adds up persistent error; D (derivative) reacts against rapid changes in measured rate. Together these form PID control. Combine these PID contributions, limit the output, and command the motors. Read the resulting motion and repeat; an incorrect motor sign makes the error grow instead of shrink.",'Actual course rate PID uses derivative on measurement, filtering, integration limits and saturation-aware anti-windup. Browser collapses the cascade into a bounded one-axis PID and displays every term.','Increase gain; compare time to recover and repeated oscillation. Flip the mixer sign and explain why each correction grows the error.',src(13,'control.c'),["Subtract estimated angle from the desired angle to get angle error.", "Convert that angle error into a desired rotation speed.", "Subtract measured rotation speed from desired speed to get rate error.", "P (proportional) responds to current error; I (integral) adds up persistent error; D (derivative) reacts against rapid changes in measured rate. Together these form PID control.", "Combine these PID contributions, limit the output, and command the motors.", "Read the resulting motion and repeat; an incorrect motor sign makes the error grow instead of shrink."],"The outer loop asks how fast to turn; the inner loop makes that turning speed happen."),
 topic("A motor pair creates a left-right turn","Each propeller pushes upward. Raising the push on one side relative to the other turns the body. This turning effect is torque. A mixer is the calculation that turns one requested roll correction into four motor commands, using the known position of each motor.","A correct tilt calculation still fails if the motor pair pushes in the wrong direction. Check which side increases before changing controller strength.","The controller requests a roll correction with a direction and size. The mixer increases one motor pair and reduces the opposite pair. Each command is limited to the permitted range from 0 to 1. Unequal upward forces create roll torque about the body centre. Torque changes rotation speed; rotation speed changes roll angle.",'M0 front-left, M1 front-right, M2 rear-right, M3 rear-left. Roll torque is proportional to T0+T3−T1−T2. Motor command range is 0…1. Yaw uses opposite propeller rotation pairs.','Select the motor stage. Check which pair increases for a negative roll correction.',src(13,'control.c'),["The controller requests a roll correction with a direction and size.", "The mixer increases one motor pair and reduces the opposite pair.", "Each command is limited to the permitted range from 0 to 1.", "Unequal upward forces create roll torque about the body centre.", "Torque changes rotation speed; rotation speed changes roll angle."],"Mixing assigns the correction to motors; torque is the turning effect their unequal forces create."),
 topic("Safety checks decide whether motors may run","Arming means allowing the motors to produce power. The switch only requests that permission. The program first checks whether the readings look usable, the throttle is low, and the estimated tilt is safe. Disarming removes motor power when a safety check fails.","A frozen or badly tilted sensor reading must interrupt correction before the motors make the situation worse. The checks still depend on an estimate, so a wrong estimate can hide real danger.","Request arming with the switch while throttle is low. Count consecutive good sensor readings and check the estimated tilt. Permit motor output only after the arming checks pass. During operation, check tilt, validity and whether new sensor samples arrive. If a check fails, set motor output to zero; cycle the switch before requesting arming again.",'Course thresholds: throttle <0.05; 125 good control steps; arm tilt <25°; disarm tilt >60°; stale sample 5 steps (20 ms). These are course policy, not universal flight rules.','With a broken sign, watch the estimated angle reach the tilt limit and motor commands become zero. Why can a biased estimate still hide real tilt?',src(13,'control.h'),["Request arming with the switch while throttle is low.", "Count consecutive good sensor readings and check the estimated tilt.", "Permit motor output only after the arming checks pass.", "During operation, check tilt, validity and whether new sensor samples arrive.", "If a check fails, set motor output to zero; cycle the switch before requesting arming again."],"An arm switch requests permission; safety checks grant and can revoke it.")],prediction:{question:'The estimate says level, but the gyro has a constant bias and α=1. What happens?',options:['The estimate self-corrects from gravity.','The estimate drifts, and the controller can tilt the real aircraft.','The bias vanishes when multiplied by dt.'],correct:1,explanations:['At α=1 the calculation uses only the gyro prediction, so the gravity clue cannot pull the angle back.','A constant gyro offset adds a small false turn at every update. The estimate drifts; the controller may move the real body to make that wrong estimate read level.','Multiplying by elapsed time makes one false angle change small; adding that change repeatedly still builds a large error.']},recap:["Keep actual angle, sensor readings and estimated angle separate.", "Correct direction must reduce error before you increase gain.", "Permission to run motors can be revoked by safety checks."],terms:[{term:'Attitude',meaning:'Which way the body is pointing: roll is left-right lean, pitch is nose-up/down lean, and yaw is turning left/right.'},{term:'Complementary filter',meaning:'Blend short-term gyro prediction with a slow gravity correction.'},{term:'Anti-windup',meaning:'Stop adding persistent error when motor output is already at its limit, so the stored correction does not grow beyond what motors can deliver.'}],sources:[src(13,'Slide.md'),src(13,'Lab.md'),src(13,'control.c'),src(13,'world.c'),src(13,'host/sitl.c')],limitations:['One-axis browser teaching plant; not quaternion SITL or a real flight measurement.','Browser PID simplifies the actual nested rate/angle controller.']},
{id:14,start:{"problem": "A drone must reach waypoints while wind and battery limits can change what it is allowed to do.", "outcome": "Trace position through speed, acceleration and tilt requests, and explain when safety replaces the mission destination.", "firstExperiment": ["Set Battery to 80% and Steady wind input to 0; press Next to follow the waypoint target and trail.", "Set Steady wind input to 6 and click Replay; compare the trail with the dotted route and read the requested tilt.", "Set Battery to 9%, then 24%; click Replay and press Next at each value. Compare LAND with RTL and look at Target x,y m."]},shortTitle:'Flying to a destination',subtitle:"Reach a destination through smaller motion requests, with safety able to change the goal.",prerequisites:[8,13],youKnow:["Motor differences can change a drone’s tilt.", "A serial message needs checks before use.", "Measured position can differ from actual position."],adds:["Position, speed and acceleration requests", "Moving between waypoints", "Battery and permitted-area safety rules"],why:'A mission must continue safely when a human is not sending each motor command.',topics:[
 topic("Break a destination into smaller motion requests","A waypoint is a target position, such as twelve metres east of home. A drone cannot turn a position directly into motion: it needs a speed, a change in speed, a tilt, and finally motor forces. Each stage turns the previous request into something the next stage can control. This chain of nested controllers is a cascade.","Position alone does not say whether the drone is already moving too fast. The smaller loops account for speed and tilt before choosing motor power.","Compare current position with the waypoint to find position error. Use that distance error to request a travel speed. Compare requested speed with current speed and request acceleration, a change in speed per second. Translate acceleration into desired tilt and upward push, called thrust. The attitude controller adjusts motor forces to produce that tilt. Motion changes the position, so the next update uses a smaller or larger position error.",'Course flight.c runs at 50 Hz. world.c abstracts lesson 13 using 80 ms attitude and 50 ms thrust lag. Coordinates are east/north/up; do not reuse body-frame signs blindly.','Step a waypoint and read the position error, desired velocity, acceleration and tilt in order.',src(14,'flight.c'),["Compare current position with the waypoint to find position error.", "Use that distance error to request a travel speed.", "Compare requested speed with current speed and request acceleration, a change in speed per second.", "Translate acceleration into desired tilt and upward push, called thrust.", "The attitude controller adjusts motor forces to produce that tilt.", "Motion changes the position, so the next update uses a smaller or larger position error."],"Destination → speed → acceleration → tilt → motor forces → new position."),
 topic("Match a delayed position reading to its own time","A Global Positioning System (GPS) position fix arrives after the position was measured. If the drone keeps moving while waiting, the fix describes an earlier location. The course estimator remembers its earlier position estimates and compares the fix with the estimate from the same time. An estimator is the calculation that builds a best available guess from imperfect readings.","Comparing an old measurement with the current position can incorrectly treat normal travel as a position error.","Use acceleration and elapsed time to predict movement. Store recent position estimates with their place in time. Receive a GPS fix describing the position 200 milliseconds earlier. Compare that fix with the stored estimate for that earlier instant. Carry the correction forward to improve the current estimate.",'GPS is 10 Hz with 200 ms delay in the course model. A 16-slot controller history covers that delay. Browser mission omits the detailed estimator and explicitly uses position truth for the outer-loop teaching example.','In the technical source, locate hx/hy and GPS_LAG_STEPS. Why would “fix minus current position” fight steady motion?',src(14,'flight.c'),["Use acceleration and elapsed time to predict movement.", "Store recent position estimates with their place in time.", "Receive a GPS fix describing the position 200 milliseconds earlier.", "Compare that fix with the stored estimate for that earlier instant.", "Carry the correction forward to improve the current estimate."],"Compare measurements and estimates from the same time before correcting position."),
 topic("Follow each route segment and allow an arrival margin","A route joins waypoints with line segments. The course controller splits the distance to the next waypoint into a distance along the segment and a distance sideways from it. It requests motion for each direction separately. That sideways distance is cross-track error. A waypoint counts as reached inside an acceptance radius: a small permitted distance from the target, rather than one mathematically exact point.","A moving drone rarely lands on an exact coordinate. Following a segment and using a tolerance makes progress possible despite wind and measurement errors.","Find the current route segment between two waypoints. Split the remaining distance to the waypoint into along-segment and sideways parts. Use the along part to move toward the waypoint and the sideways part to return toward the route line. Limit requested travel speed so the aircraft can follow the route. When distance to the waypoint enters the acceptance radius, advance to the next segment.",'The course supports line following versus point aiming, acceptance radius, cruise speed and cross-track scoring. Browser uses four point targets to expose the hierarchy; it does not reproduce original line guidance.','Raise wind and compare the visible trail with the intended waypoint path. Why is “waypoint reached” a tolerance rather than equality?',src(14,'flight.c'),["Find the current route segment between two waypoints.", "Split the remaining distance to the waypoint into along-segment and sideways parts.", "Use the along part to move toward the waypoint and the sideways part to return toward the route line.", "Limit requested travel speed so the aircraft can follow the route.", "When distance to the waypoint enters the acceptance radius, advance to the next segment."],"Follow the route line; reach a waypoint within its allowed distance."),
 topic("Low battery can replace the mission goal","A safety rule can change the destination even during a mission. Return to launch, abbreviated RTL, means go home before landing. A geofence is a permitted area; leaving it can also trigger return. Critical battery means there may be too little energy left for the trip home, so the course policy requests landing at the present location.","Check the most urgent condition first. At 9% battery, both low and critical thresholds are crossed, but the critical rule must win.","Check whether battery is below the critical threshold. If critical, choose LAND at the present location and stop checking less urgent battery rules. Otherwise, low battery or crossing the permitted boundary selects RTL. RTL targets home; after arriving, the full course controller lands and disarms. The browser represents LAND by holding horizontal position and does not simulate descent.",'Course default BAT_LOW=25%, BAT_CRIT=10%, geofence radius=50 m. Critical check returns before low-battery logic. Browser shows LAND stopping horizontal mission progression; descent is represented conceptually.','Set battery to 9% and then 24%. Predict why the targets differ. Inspect the original modes and landing implementation.',src(14,'flight.c'),["Check whether battery is below the critical threshold.", "If critical, choose LAND at the present location and stop checking less urgent battery rules.", "Otherwise, low battery or crossing the permitted boundary selects RTL.", "RTL targets home; after arriving, the full course controller lands and disarms.", "The browser represents LAND by holding horizontal position and does not simulate descent."],"Critical battery: land here. Low battery: return home if the critical rule has not fired."),
 topic("Check both message bytes and mission meaning","The ground station sends waypoint commands over a serial link called UART. A frame marks where one message starts and ends. A checksum helps detect changed bytes, but a perfectly transmitted message can still ask for an impossible or unsafe route. The aircraft checks the list and coordinates before accepting it.","Successful transmission is only the first check. A mission must also fit storage, include complete waypoint entries, and stay inside permitted bounds.","Receive a complete framed message from the serial link. Check its checksum to detect damaged bytes. Parse fields without exceeding the available storage. Check coordinate ranges, waypoint continuity and the permitted flight boundary. Send an acknowledgement, or ACK, for an accepted command; refuse invalid commands.",'MAVLink-lite is course-specific $BODY*XOR framing, not MAVLink binary/CRC16. Empty/gapped missions and out-of-fence waypoints are refused. Link-loss timeout is not a failsafe implemented by this lesson.','Open host/default.mission and mavlite.c. Identify byte validation versus mission meaning validation.',src(14,'mavlite.h'),["Receive a complete framed message from the serial link.", "Check its checksum to detect damaged bytes.", "Parse fields without exceeding the available storage.", "Check coordinate ranges, waypoint continuity and the permitted flight boundary.", "Send an acknowledgement, or ACK, for an accepted command; refuse invalid commands."],"Checksum asks “did these bytes survive?” Mission validation asks “is this request allowed?”")],prediction:{question:'Battery is 9%, below both battery thresholds. Which mode should win?',options:['RTL because 9 is below 25.','LAND in place because critical battery is checked first.','Continue until next waypoint.'],correct:1,explanations:['Returning may spend energy the aircraft no longer has.','At 9%, the critical check fires first and chooses LAND here. Returning home might use energy the drone no longer has.','Safety changes mode before mission guidance.']},recap:["A waypoint becomes speed, acceleration and tilt before motor power.", "A late sensor fix must be compared with an estimate from the same time.", "Check mission meaning before flying; let urgent safety rules replace the goal."],terms:[{term:'RTL',meaning:'Return to launch/home before landing.'},{term:'Geofence',meaning:'A boundary that constrains permitted flight.'},{term:'Cross-track error',meaning:'Sideways distance from the intended route segment.'}],sources:[src(14,'Slide.md'),src(14,'Lab.md'),src(14,'flight.c'),src(14,'mavlite.c'),src(14,'host/mission.py')],limitations:['Browser point-guidance model is not original mission SITL.','No real GPS, vehicle, battery measurement or complete landing dynamics.']},
{id:15,start:{"problem": "A wheeled robot must follow tape using only seven nearby darkness readings.", "outcome": "Explain how readings become line position, how two steering contributions change wheel speeds, and why no reading means unknown.", "firstExperiment": ["Set Kp to 20, Kd to 1, Base speed to 650 mm/s and Sensor noise amplitude to 0.", "Press Next, then select Sensor 0 and Sensor 3. Compare each darkness reading, its sideways position and its dark weight.", "Set Kd to 0 and click Replay; advance through the path again. Compare the wheel-speed difference and path with the original run."]},shortTitle:'Following a line',subtitle:"Turn nearby darkness readings into a position and two wheel speeds.",prerequisites:[9,13],youKnow:["Sensors report imperfect numbers.", "A correction changes the next reading.", "Different wheel speeds turn a robot."],adds:["Averaging sensor positions by darkness", "Steering from error and its rate of change", "Reducing corner speed and recovering lost tape"],why:'A robot cannot read a track diagram; it must infer the line from a few nearby sensors.',topics:[
 topic("Estimate where the tape lies under seven sensors","Seven sensors sit across the front of the robot. Each reports darkness under its own patch. Subtract the background threshold to keep evidence of tape, then give darker patches more influence in the average sensor position. The resulting position tells the controller how far the line is from the sensor bar centre.","Using all readings gives a smoother position than selecting one darkest sensor. With no dark evidence, there is no position to average.","Read darkness from all seven patches. Subtract the threshold and discard negative weights. Multiply each remaining darkness weight by that sensor’s sideways position. Add those products and divide by the total weight to estimate line position. If the total weight is too small, report line position as unknown instead of reporting zero.",'Course spacing is 13 mm; bar spans −39…+39 mm. Position = Σ(weight × sensor position)/Σweight. + means left in course robot coordinates. Browser top-down screen uses +horizontal toward the visible line.','Vary noise; compare raw readings to weighted position. With no weight, why is zero not a valid “centred line” reading?',src(15,'control.c'),["Read darkness from all seven patches.", "Subtract the threshold and discard negative weights.", "Multiply each remaining darkness weight by that sensor’s sideways position.", "Add those products and divide by the total weight to estimate line position.", "If the total weight is too small, report line position as unknown instead of reporting zero."],"More darkness gives a sensor more weight; no weight means unknown, not centred.",'float w = (float)in->line[i] - g->thr;\nfloat y = (float)((i - (LINE_SENSORS - 1) / 2) * SENSOR_PITCH_MM);\nsw  += w;\nswy += w * y;'),
 topic("Steer toward the tape and limit swinging","Kp sets how strongly steering responds to the current sideways line error. Kd sets how strongly it responds to the speed at which that error changes. These are proportional and derivative gains, together called PD. The program adds their contributions to make one wheel faster and the other slower, which turns the robot.","A motor response takes time. Looking at how fast the error changes can reduce repeated overshoot, but noisy readings also create abrupt changes, so the derivative is filtered.","Estimate the line’s sideways distance from the centre. Multiply the current error by Kp to obtain the P steering contribution. Calculate error change per second, smooth it, and multiply by Kd to obtain D. Add P and D to obtain the requested wheel-speed difference. Subtract steering from one wheel’s base speed and add it to the other. The turn changes the next sensor reading; delayed motors can cause the robot to pass the line before correction settles.",'Actual course defaults Kp=20, Ki=0, Kd=1, derivative filter=0.5. Commands are mm/s and clamped ±2000. Browser uses the same weighted position and PD algebra but a reduced track/plant.','Set Kd=0, run, then restore Kd=1. Compare the path and D contribution, rather than memorizing “D is good”.',src(15,'control.c'),["Estimate the line’s sideways distance from the centre.", "Multiply the current error by Kp to obtain the P steering contribution.", "Calculate error change per second, smooth it, and multiply by Kd to obtain D.", "Add P and D to obtain the requested wheel-speed difference.", "Subtract steering from one wheel’s base speed and add it to the other.", "The turn changes the next sensor reading; delayed motors can cause the robot to pass the line before correction settles."],"Kp reacts to error now; Kd reacts to how fast that error changes.",'float turn = g->kp * e + g->ki * i_acc + g->kd * d_filt;\nout->left  = clamp_mms(v - turn);\nout->right = clamp_mms(v + turn);'),
 topic("Reduce speed when a corner needs more grip","A tyre needs grip to turn as well as to move forward. Near a sharp corner, reducing the speed both leaves more grip for turning and makes the robot travel less distance between sensor checks. Wheel encoders count wheel rotation; a spinning or sliding tyre can therefore report travel that the body did not make.","Higher commanded speed can lose the line and worsen completion time. Wheel counts alone cannot prove the robot followed the track.","A corner moves the sensed line toward the edge of the sensor bar. Reduce forward base speed while keeping steering correction available. Less travel between updates gives the controller more chances to turn before leaving the tape. In the full course model, grip also limits how much force the tyres can supply. If a tyre slips, its encoder still counts rotation even though body travel differs.",'Original world.c models motor lag, traction/friction-circle limits and wheel encoders. Browser models lag but omits traction; no browser lap time is a course benchmark.','Increase speed without changing gains. If sensors lose the line, explain the causal chain from travel distance per control step.',src(15,'world.c'),["A corner moves the sensed line toward the edge of the sensor bar.", "Reduce forward base speed while keeping steering correction available.", "Less travel between updates gives the controller more chances to turn before leaving the tape.", "In the full course model, grip also limits how much force the tyres can supply.", "If a tyre slips, its encoder still counts rotation even though body travel differs."],"Forward speed uses both distance between checks and available tyre grip."),
 topic("Choose a recovery when the line disappears","When no sensor sees enough darkness, the line position is unknown. The last known position gives a clue: if it was near the centre, the robot may be crossing a small gap; if it was near an edge, the robot may have missed a turn. The course uses that clue to choose brief straight travel or a search turn.","Missing evidence needs a separate decision. Dividing by zero or inventing a centred line would send the wheels the wrong instruction.","Calculate total darkness weight. If it is too low, stop treating the current average as a valid line position. Keep the last valid position as a recovery clue. Near centre, coast briefly through a possible tape gap; near an edge, search toward the remembered side. At a crossing, several sensors see darkness together; preserve prior steering and avoid a sudden derivative correction.",'Course MIN_WEIGHT=60, GAP_POS_MM=12, COAST_MS=400, SEARCH_MMS=500. Five dark sensors indicate a crossing; preserve prior steering and avoid a derivative spike.','Drive too fast until the browser marks LINE LOST. Locate the actual gap and crossing policies before proposing a recovery.',src(15,'control.c'),["Calculate total darkness weight.", "If it is too low, stop treating the current average as a valid line position.", "Keep the last valid position as a recovery clue.", "Near centre, coast briefly through a possible tape gap; near an edge, search toward the remembered side.", "At a crossing, several sensors see darkness together; preserve prior steering and avoid a sudden derivative correction."],"Unknown line position needs recovery; the last valid position tells you where to begin."),
 topic("Give the controller one consistent sensor reading","Different scheduled jobs, called tasks, read sensors, calculate wheel commands, simulate motion, and update the display. A snapshot is a copied set of values from one update. The controller needs a complete snapshot, so it does not combine some old readings with some new ones while another task is writing.","Even correct steering maths can turn the wrong way with a mixed reading. Slow drawing must also leave time for the next control update.","The sensor task finishes a set of readings. Copy that set under a brief protection rule that prevents another task from changing it during the copy. The controller reads the complete copy and computes wheel commands. Publish a complete output snapshot for motion and display tasks. Let the slower display draw its copy while the controller continues on schedule.",'Course uses five tasks, protected copies and UART $LAP/$TEL data. Host leaderboard verifies framed results; MCU timing must be measured separately.','Open Main.c and find the critical section around snapshot copies. Which data must stay consistent together?',src(15,'Main.c'),["The sensor task finishes a set of readings.", "Copy that set under a brief protection rule that prevents another task from changing it during the copy.", "The controller reads the complete copy and computes wheel commands.", "Publish a complete output snapshot for motion and display tasks.", "Let the slower display draw its copy while the controller continues on schedule."],"One snapshot means one coherent update, not a mixture of old and new values.")],prediction:{question:'All seven readings fall below threshold. Does weighted position equal zero?',options:['Yes: line is centred.','No: position is unknown and recovery policy must take over.','Yes: the controller should accelerate.'],correct:1,explanations:['No evidence is different from evidence of centre.','The total darkness weight is too small for a valid average. The course uses the last position to choose a search turn or brief coast; the browser searches.','Accelerating while blind can lose the track.']},recap:["Darkness weights produce estimated line position; too little weight means unknown.", "Kp responds to current error; Kd responds to error change per second.", "Slow corners and explicit lost-line decisions matter as much as steering gains."],terms:[{term:'PD / Kp / Kd',meaning:'Proportional-derivative steering: Kp multiplies current error, Kd multiplies its change per second; filtering smooths rapid changes.'},{term:'Differential drive',meaning:'Two separately driven wheels; making one wheel faster than the other turns the robot.'},{term:'Encoder',meaning:'Counts wheel rotation, including rotation caused by slip.'}],sources:[src(15,'Slide.md'),src(15,'Lab.md'),src(15,'control.c'),src(15,'world.c'),src(15,'host/sitl.c')],limitations:['Reduced browser track and motor dynamics; original traction, lap judge and crossing tracks available in source.']},
{id:16,start:{"problem": "A robot initially plans through space where it has not yet discovered a wall.", "outcome": "Distinguish the true world, the robot’s map and its route, and trace how new evidence changes the plan.", "firstExperiment": ["Keep Add unknown wall on direct route checked. At the first frame, compare the wall on the left with the map on the right.", "Press Next until New obstacle evidence becomes yes; watch the right-hand map and route change.", "Uncheck Add unknown wall on direct route and click Replay. Press Next again and compare the route cells remaining."]},shortTitle:'Finding a path around obstacles',subtitle:"Discover walls, update a map, and replace a route when it becomes blocked.",prerequisites:[15],youKnow:["Sensors observe only part of the surroundings.", "Different wheel speeds can steer toward a local target."],adds:["A map of observed free, blocked and unknown cells", "Searching for routes with A*", "Braking immediately and replacing blocked routes"],why:'A route can be wrong because the robot has never seen the obstacle that blocks it.',topics:[
 topic("Build the map from observations, not hidden walls","The real room contains walls whether the robot has seen them or not. Its map records what sensor evidence currently says about each small square, or cell. This occupancy map is a belief about free, blocked or unknown space. A planner is the program that chooses a route using that map.","Keeping hidden walls out of the planner makes discovery matter. A reasonable route through unknown space may need changing after a sensor finds an obstacle.","A nearby wall produces a distance reading. Use the reading to update cells in the robot’s map. Keep cells without evidence unknown. The planner chooses a route using that map; this course permits travel through unknown cells. When a new observation marks a route cell blocked, replace the route.",'Original course map is 32×14 cells. Browser uses a 12×7 grid for readability. Unknown space is optimistically allowed in planning; a separate true-world view is only for the learner.','Step until the hidden wall is detected. Compare the two maps before and after observation.',src(16,'nav.c'),["A nearby wall produces a distance reading.", "Use the reading to update cells in the robot’s map.", "Keep cells without evidence unknown.", "The planner chooses a route using that map; this course permits travel through unknown cells.", "When a new observation marks a route cell blocked, replace the route."],"World is what exists; map is what the robot currently believes; route is what it plans to do."),
 topic("Place distance readings using an estimated position","The robot must know where it was pointing and standing when a sensor reading arrived. Position plus heading is called pose. Counting wheel rotation and measuring turn speed gives an estimate of changing pose; this is dead reckoning. If a wheel slips, the estimated position can drift, so even an accurate wall distance can be written into the wrong map cell.","Mapping depends on both the distance reading and the pose used to place it. A bad position estimate can make a good sensor appear wrong.","Calibrate the gyro while the robot is still to estimate its constant error. Use wheel counts and measured turn rate to update estimated position and heading. Turn each sensor beam from robot-relative direction into map coordinates using that pose. Mark cells along the beam as evidence of free space and the hit cell as evidence of a wall. Repeat observations to strengthen or weaken confidence; pose errors can place the evidence incorrectly.",'Course starts with still gyro calibration, then encoder/gyro odometry. Occupancy evidence is integer bounded confidence; free cells along rays and occupied hits update differently. Browser uses exact cell pose and binary occupied belief, explicitly simplifying localization and evidence.', 'Why could an accurate distance reading still create a misplaced wall? Inspect nav.c pose and ray-update code.',src(16,'nav.c'),["Calibrate the gyro while the robot is still to estimate its constant error.", "Use wheel counts and measured turn rate to update estimated position and heading.", "Turn each sensor beam from robot-relative direction into map coordinates using that pose.", "Mark cells along the beam as evidence of free space and the hit cell as evidence of a wall.", "Repeat observations to strengthen or weaken confidence; pose errors can place the evidence incorrectly."],"A distance says how far; pose says where that distance belongs on the map."),
 topic("Search for a low-cost route with A*","A* is a route-search method. For each candidate cell it adds the travel cost already spent, called g, to an estimate of the cost still needed to reach the goal, called h. It explores a promising candidate next and remembers which earlier cell led there, so it can reconstruct the route after reaching the goal.","This ordering can reduce search work compared with blindly checking routes. It still needs a trustworthy map and a distance estimate suited to allowed moves.","Put the starting cell into the candidate list with zero cost so far. Consider allowed neighbouring cells and skip blocked ones. For each candidate, compute g+h: cost so far plus estimated remaining cost. Explore the candidate with the lowest score and remember its predecessor. When the goal is reached, follow those predecessor links backward to recover the route.",'Browser A* uses four-connected Manhattan distance, unit costs, stable ordering and occupied-cell exclusion. Course astar.c adds bounded arrays and a costmap with obstacle inflation/near-wall cost.','Discover a wall and watch the shortest available route go around it. Remove the wall and compare route length.',src(16,'astar.c'),["Put the starting cell into the candidate list with zero cost so far.", "Consider allowed neighbouring cells and skip blocked ones.", "For each candidate, compute g+h: cost so far plus estimated remaining cost.", "Explore the candidate with the lowest score and remember its predecessor.", "When the goal is reached, follow those predecessor links backward to recover the route."],"A* ranks next steps by cost already spent plus estimated cost still ahead."),
 topic("Turn a grid route into motion and stop for danger","A route is a list of map positions, not wheel speeds. The full course controller chooses a point ahead on the route and steers toward it; this method is pure pursuit. A separate near-obstacle check can brake immediately while the planner calculates a replacement route.","The wheels need a smooth motion request, and immediate stopping cannot wait for a long route search to finish.","Read the current route and choose a point a short distance ahead. Use its direction to calculate how sharply to turn. Convert that turn and forward speed into left and right wheel commands. Check nearby obstacle distance independently of the route search. Brake if danger is close, then resume with a safe replacement route.",'Course uses pure pursuit, obstacle inflation, a reactive brake and explicit replanning triggers. Browser moves cell-to-cell to isolate observation → map → search causality.','Explain why braking must not wait for A* to finish. Inspect the replan and brake conditions.',src(16,'nav.c'),["Read the current route and choose a point a short distance ahead.", "Use its direction to calculate how sharply to turn.", "Convert that turn and forward speed into left and right wheel commands.", "Check nearby obstacle distance independently of the route search.", "Brake if danger is close, then resume with a safe replacement route."],"Planner chooses where to go; wheel control chooses how to move; nearby danger can stop both."),
 topic("Leave enough time and memory for route search","The processor has to search for routes while also reading sensors and controlling wheels. A deadline is the latest allowed finish time for a job. Bound the number of cells and work in a search so one difficult route does not delay the next control job. Publish a finished route as a complete copy.","A route that eventually succeeds is not useful if its computation prevents timely braking or exhausts memory.","New obstacle evidence makes the current route unusable. Request a search with bounded storage and work. Keep sensing and immediate safety checks running while the route is prepared. Publish the completed route snapshot. Measure search work on the intended processor before claiming control deadlines are met.",'Course host/planner.py benchmarks host search separately from MCU execution; host seconds are not MCU timing. A* memory and expansion counts can be compared; actual cycle counts need target evidence.','Track which cells changed and which route was replaced. Would every new free-cell observation require replanning?',src(16,'host/planner.py'),["New obstacle evidence makes the current route unusable.", "Request a search with bounded storage and work.", "Keep sensing and immediate safety checks running while the route is prepared.", "Publish the completed route snapshot.", "Measure search work on the intended processor before claiming control deadlines are met."],"Route quality, search memory and time to finish are three separate checks.")],prediction:{question:'An unseen wall is on the planned route. Why can the initial route cross it?',options:['The planner has access to truth and ignores it.','Unknown cells are treated as traversable until sensors add evidence.','A* cannot route around walls.'],correct:1,explanations:['The robot does not receive truth coordinates.','No observation has marked that cell blocked. Allowing unknown cells enables exploration, but new evidence and immediate braking must protect the robot.','Once the map marks the wall, A* can find an alternative.']},recap:["World, map and route describe reality, belief and intention.", "New obstacle evidence can invalidate a reasonable earlier route.", "Route search chooses where to go; immediate braking handles nearby danger."],terms:[{term:'Occupancy grid',meaning:'Cells recording belief about free, occupied or unknown space.'},{term:'A*',meaning:'Path search prioritizing cost so far plus an estimated remaining cost.'},{term:'Pure pursuit',meaning:'Steer toward a look-ahead point on a route.'}],sources:[src(16,'Slide.md'),src(16,'Lab.md'),src(16,'nav.c'),src(16,'astar.c'),src(16,'host/planner.py')],limitations:['Browser simplifies rays, pose estimation, evidence confidence and continuous drive; exact original code is linked.']},
{id:17,start:{"problem": "A robot can recover upright after a push yet roll away from its starting position.", "outcome": "Compare angle recovery with position recovery and explain which controller observes each quantity.", "firstExperiment": ["Set Controller to PID tilt, Push impulse to 0.08 N·s and Payload to 0 kg.", "Press Next until Time s passes 0.20, when the push occurs. Compare Angle ° with Axle position m and both response plots.", "Select cascade, then LQR, clicking Replay for each. Keep the same push and payload, and compare return to upright with return to the dashed home line."]},shortTitle:'Keeping a robot upright',subtitle:"Compare staying upright with returning to the starting position.",prerequisites:[13,15],youKnow:["Motion sensors can help estimate tilt.", "A motor correction changes the next observation.", "Battery voltage limits available motor output."],adds:["How wheel motion and body lean affect one another", "Tilt control and a position-to-tilt cascade", "A four-state correction designed with LQR"],why:'Keeping a body upright is different from keeping the whole robot in one place.',topics:[
 topic("Move the axle under a body that is tipping","A balancing robot holds its body above two wheels. Gravity makes a small lean grow instead of restoring it, like balancing a stick on your hand. The motors move the axle under the falling body. Their turning force, or torque, also acts on the body, so wheel motion and body tilt affect each other.","Keeping wheels still cannot catch a falling body. The useful correction may initially move the robot in the direction it is falling.","A push or initial lean moves the body away from upright. Gravity creates torque that increases the lean and rotation speed. The controller requests motor voltage. Motor torque moves the wheels and reacts on the body. The changed axle position and body motion can bring the body back above its support.",'Browser ports course params.h/world.c nonlinear two-coordinate mass-matrix equations, 1 ms semi-implicit integration, battery voltage limit and a 20 ms push. It uses JavaScript arithmetic and perfect-state sensing, so results are not identical course SITL.','Set disturbance, step across 0.20 s, then watch wheels and angle. Which must move first to recover?',src(17,'world.c'),["A push or initial lean moves the body away from upright.", "Gravity creates torque that increases the lean and rotation speed.", "The controller requests motor voltage.", "Motor torque moves the wheels and reacts on the body.", "The changed axle position and body motion can bring the body back above its support."],"To recover balance, move the support under the falling body."),
 topic("Acceleration can look like tilt to a sensor","An accelerometer reading changes when the robot accelerates, even if its angle does not change. A gyro measures turning speed and helps predict angle between readings. The full course combines both to estimate tilt, then combines wheel rotation with body tilt to estimate axle travel. The browser instead supplies exact state to make controller comparisons easier to interpret.","A controller acts on the estimate, so apparent tilt caused by acceleration can request an unnecessary correction. Wheel rotation also needs the body’s motion to locate the axle correctly.","Use the gyro rate and elapsed time to predict the new tilt. Apply a small accelerometer-based correction to limit drift. Combine encoder rotation with estimated body tilt to estimate axle travel. Compare successive travel estimates to estimate speed and smooth that result. Use the estimates in the course controller; remember that the browser comparison removes these sensor errors.",'Course uses α=.98 at 200 Hz, a 1° mounting error, .005 rad/s gyro bias and quantized 1440-count encoder. Browser comparison uses truth as estimate so controller differences remain visible; sensor error is taught separately.','Open estimate() in control.c. Why does wheel angle include estimated body tilt?',src(17,'control.c'),["Use the gyro rate and elapsed time to predict the new tilt.", "Apply a small accelerometer-based correction to limit drift.", "Combine encoder rotation with estimated body tilt to estimate axle travel.", "Compare successive travel estimates to estimate speed and smooth that result.", "Use the estimates in the course controller; remember that the browser comparison removes these sensor errors."],"The full robot estimates its state; the browser comparison gives controllers the exact state."),
 topic("Holding upright does not guarantee staying in place","Tilt PID adjusts voltage using three clues: present tilt error, tilt error accumulated over time, and rotation speed. P means proportional response, I means accumulated error, and D means response to change. This can keep the body upright while the wheels continue rolling, because axle position is not one of the clues.","Angle recovery and position recovery answer different questions. A small angle plot alone cannot prove the robot returned home.","Compare tilt with the requested upright angle. Use present error, accumulated error and angular rate to calculate motor voltage. Limit voltage to the available battery supply. The wheels move to restore balance. If the controller never reads position or speed, it has no direct instruction to return the axle home.",'Actual gains: 150 V/rad, 50 V/(rad·s), 4 V/(rad/s), integral clamp ±.1 rad·s. Battery clamps voltage to ±7.4 V. Browser uses those gains with perfect state.','Run identical push with all three controllers. Compare position and angle plots separately.',src(17,'control.c'),["Compare tilt with the requested upright angle.", "Use present error, accumulated error and angular rate to calculate motor voltage.", "Limit voltage to the available battery supply.", "The wheels move to restore balance.", "If the controller never reads position or speed, it has no direct instruction to return the axle home."],"Upright describes angle; home describes position. Tilt control observes only the first."),
 topic("Choose a lean that brings the wheels home","A cascade uses one controller inside another. The outer controller reads position and travel speed and chooses a small desired lean. The inner controller quickly adjusts motor voltage to hold that lean. Leaning lets the robot accelerate or slow down, so balance correction can also restore position.","Always asking for upright gives no direct way to return to a location. Position control needs to request a lean that the balancing loop can safely produce.","Compare axle position and travel speed with their targets. The outer controller converts these errors into a desired lean. Limit that lean to a safe range. The inner tilt controller compares actual lean with desired lean and chooses voltage. Wheel motion changes speed and position, which updates the next outer-loop request.",'Course CAS_KPX=.20, CAS_KVX=.60, inner CAS_KP=25, CAS_KD=2. A speed command is ramp-limited .5 m/s². Browser target is fixed at home.','Add payload; compare recovery. Explain why outer position control must cooperate with fast balancing, not overwrite its output.',src(17,'control.c'),["Compare axle position and travel speed with their targets.", "The outer controller converts these errors into a desired lean.", "Limit that lean to a safe range.", "The inner tilt controller compares actual lean with desired lean and chooses voltage.", "Wheel motion changes speed and position, which updates the next outer-loop request."],"Position loop chooses the lean; balance loop makes that lean happen."),
 topic("Use position, speed, tilt and turn speed together","The state is the set of numbers describing the robot now: axle position, travel speed, tilt angle, and tilt rate. LQR means linear quadratic regulator. It is a method for calculating four gains from a simplified motion model and chosen penalties for errors and motor effort. Multiplying each state error by its gain and adding the results produces the voltage request.","These four quantities affect one another. A jointly designed correction can account for that coupling, but gains depend on the model used to calculate them.","Measure or estimate position, travel speed, tilt and tilt rate. Subtract desired position and speed to obtain their errors. Multiply each state quantity by its corresponding designed gain. Add the contributions and reverse the sum’s sign to form the voltage correction. Limit voltage to the battery supply and recheck performance when mass or other model assumptions change.",'Course K=[−5.1239,−15.255,−21.262,−2.4627]; u=−Kx. host/lqr.py designs from params.h using Q=diag(30,2,50,.5), R=1 and 5 ms control sampling. This optimizes a linearized model, not every nonlinear operating condition.','Increase payload without redesigning gains. Why should a K designed for one mass be rechecked for another?',src(17,'control.c'),["Measure or estimate position, travel speed, tilt and tilt rate.", "Subtract desired position and speed to obtain their errors.", "Multiply each state quantity by its corresponding designed gain.", "Add the contributions and reverse the sum’s sign to form the voltage correction.", "Limit voltage to the battery supply and recheck performance when mass or other model assumptions change."],"LQR uses four state quantities together; its gains belong to the model they were designed for.",'u = -(LQR_K[0] * (est.x - est.x_ref)\n    + LQR_K[1] * (est.xd - est.v_ref)\n    + LQR_K[2] * est.th\n    + LQR_K[3] * in->gyro);')],prediction:{question:'A controller keeps tilt near zero but the robot rolls away. What is missing?',options:['A faster display.','Position/speed feedback.','Another angle-only integral.'],correct:1,explanations:['Drawing does not set the physical equilibrium.','The controller observes lean but has no direct correction for axle position or travel speed. Cascade and LQR add those quantities so returning home becomes a goal.','Accumulating angle error does not observe axle position.']},recap:["An upright body can still be rolling away.", "Compare controllers using the same push and payload, watching angle and position.", "Changed mass, sensor errors and voltage limits can invalidate a good-looking response."],terms:[{term:'Inverted pendulum',meaning:'A mass balanced above a support, unstable without correction.'},{term:'LQR',meaning:'Linear quadratic regulator: a design method that chooses gains from a simplified motion model and penalties for state errors and motor effort.'},{term:'State vector',meaning:'Numbers describing the system now, such as position, speed, angle and angular rate.'}],sources:[src(17,'Slide.md'),src(17,'Lab.md'),src(17,'params.h'),src(17,'world.c'),src(17,'control.c'),src(17,'host/lqr.py')],limitations:['Course plant/gains port with perfect-state sensing; no original sensor noise, bias, estimator or soft-float timing.','Plots are deterministic browser simulation, not target measurements.']},
{id:18,start:{"problem": "A sumo robot must find an opponent without driving itself over the ring edge.", "outcome": "Explain how limited sensors and the order of decision rules choose search, attack or escape.", "firstExperiment": ["Check Robot 1 checks edge before attacking and Edge-danger starting position.", "Press Next while reading Edge sensor mask, Forward range and Robot 1’s state. Watch which condition selects its next wheel command.", "Uncheck Robot 1 checks edge before attacking, reset, and replay the same start. Compare the decision and outcome when danger and attack compete."]},shortTitle:'Making decisions in a robot match',subtitle:"Choose search, attack or escape from the robot’s limited sensor evidence.",prerequisites:[15,16],youKnow:["Wheel commands change position and heading.", "A sensor sees only part of the world.", "A strategy can remember a current behaviour."],adds:["A strategy limited to its own sensor packet", "Fair decisions from the same observation time", "Repeatable matches and maximum execution work"],why:'A convincing strategy survives imperfect perception, edge danger and an opponent—not just a favourable animation.',topics:[
 topic("Give each robot only its own sensor evidence","The viewer can see both robots from above, but the strategy program receives only a sensor packet: distance readings, edge detections, contact and other permitted measurements. The referee is the program that knows the whole world and judges the match. Giving referee positions to the robot would bypass the problem of finding an opponent with sensors.","A fair comparison asks what a real robot could decide from its observations, including when an opponent is outside its view.","Freeze one world snapshot for the next decision. Build each robot’s sensor packet from that same instant. Run both strategies using their own packets and private memory. Latch both wheel commands before moving either robot. Advance motion and create the next shared observation time.",'Original robot_view_t contains 3 distance readings, 4 edge bits, bump bits, wheel encoders, match time and scores. It contains no position or opponent velocity. Browser uses one forward cone, four corner-edge bits and contact.','Pause when an opponent is outside the cone. Strategy must search even though you can see the opponent.',src(18,'strategy.h'),["Freeze one world snapshot for the next decision.", "Build each robot’s sensor packet from that same instant.", "Run both strategies using their own packets and private memory.", "Latch both wheel commands before moving either robot.", "Advance motion and create the next shared observation time."],"The viewer sees the world; the strategy receives only its permitted sensor packet."),
 topic("Escape the edge before chasing the opponent","The robot chooses among behaviours such as SEARCH, ATTACK and ESCAPE. Keeping one current behaviour and rules for changing it is a state machine. A white edge reading means a wheel may soon leave the ring, so the safe strategy checks edge danger before deciding to attack a visible opponent. Escape direction depends on which corner sensors see the edge.","Seeing a target and seeing danger can happen together. Decision order determines which action wins.","Read the latest edge, opponent-distance and contact sensors. If edge danger has priority, select ESCAPE: reverse away from a front edge, move forward from a rear edge, or pivot away from a side edge. Otherwise, seeing an opponent or contact selects ATTACK. With neither clue, select SEARCH and turn in a scanning arc. The wheel commands change the next sensor readings and may cause another state change.",'Course student.c adds remembered target direction and timers; built-ins Bull, Matador, Spinner, Turtle and Coward use different finite states. Browser is a minimal sensor-only three-state strategy.','Toggle edge priority off and replay the same starting geometry. Inspect decisions and explain any self-out.',src(18,'student.c'),["Read the latest edge, opponent-distance and contact sensors.", "If edge danger has priority, select ESCAPE: reverse away from a front edge, move forward from a rear edge, or pivot away from a side edge.", "Otherwise, seeing an opponent or contact selects ATTACK.", "With neither clue, select SEARCH and turn in a scanning arc.", "The wheel commands change the next sensor readings and may cause another state change."],"When target and edge appear together, the earlier decision rule wins."),
 topic("An encoder can count wheels that are slipping","A motor can spin a wheel even when an opponent pins the robot. Tyre grip limits the force that reaches the ground, and contact changes body motion. An encoder counts wheel rotation, so it cannot by itself distinguish useful travel from slipping. This matters when estimating position during a fight.","A large forward command or wheel count is not evidence that the body moved forward.","Apply motor voltage to request wheel torque. Tyre grip limits the force transmitted to the ground. Contact with the opponent changes the resulting body motion. The encoder still counts wheel rotation during slipping or pinning. A position estimate based only on wheel counts can therefore drift from actual position.",'Original world.c models longitudinal/lateral friction, back-EMF and contact impulses; side pushes have different resistance. Browser uses a reduced equal-mass inelastic contact rule and does not claim tournament fidelity.','When both attack head-on, compare wheel command with actual movement. Why is dead reckoning unreliable during contact?',src(18,'world.c'),["Apply motor voltage to request wheel torque.", "Tyre grip limits the force transmitted to the ground.", "Contact with the opponent changes the resulting body motion.", "The encoder still counts wheel rotation during slipping or pinning.", "A position estimate based only on wheel counts can therefore drift from actual position."],"Wheel rotation is a measurement of the wheel, not a guarantee of body travel."),
 topic("Replay the same observations for a fair comparison","A deterministic run gives the same result from the same starting conditions and inputs. If a strategy needs random choices, a seed fixes their repeatable sequence. Each robot also needs its own memory so one strategy does not accidentally change another’s decisions. A match hash is a compact value used to compare recorded outcomes or traces.","Without repeatability, a changed result may come from chance or shared state rather than the rule you edited.","Choose a fixed seed and starting conditions. Clear and separate each robot’s private strategy memory. Generate the same observation sequence for unchanged inputs. Record decisions and resulting motion. Replay unchanged controls first, then change one rule and locate the first changed decision.",'Course strategy_mem_t is 64 bytes, zeroed each round; private state must fit it. Course referee uses 3 s countdown, 20 s fight and best of three. Browser offers one deterministic teaching round, not league scoring.','Replay without changing controls. Find the first different decision only after changing edge priority.',src(18,'referee.c'),["Choose a fixed seed and starting conditions.", "Clear and separate each robot’s private strategy memory.", "Generate the same observation sequence for unchanged inputs.", "Record decisions and resulting motion.", "Replay unchanged controls first, then change one rule and locate the first changed decision."],"Same start and inputs should reproduce the same decisions before you compare an edit."),
 topic("Finish every strategy call before its time limit","A strategy call is one execution of the decision program. It must finish before the next scheduled control update. Worst case means the longest execution, such as a difficult search, rather than the average over easy calls. A cycle budget counts the processor clock cycles permitted for that work.","A fast average can hide one slow decision that delays motion control. Desktop execution time does not tell you how many cycles the microcontroller needs.","Read a target timing counter before calling the strategy. Run the decision and read the counter afterward. Calculate work for that call and keep the largest observed value. Compare it with the allowed cycle budget and investigate longer possible cases. Separately check repeatability and integrity; a correct hash does not establish timely execution.",'Course budget is 20,000 cycles per strategy call; control runs each 20 ms while physics steps each 5 ms. Host hashes verify repeatability, but PC time and PC floating point do not prove MCU timing.','Open host/strategies/cheater.c and host/league.c. Distinguish integrity checks from execution-budget checks.',src(18,'host/league.c'),["Read a target timing counter before calling the strategy.", "Run the decision and read the counter afterward.", "Calculate work for that call and keep the largest observed value.", "Compare it with the allowed cycle budget and investigate longer possible cases.", "Separately check repeatability and integrity; a correct hash does not establish timely execution."],"Worst-case timing asks whether the slowest allowed call still finishes in time.")],prediction:{question:'The viewer sees an opponent behind the robot. What may the strategy use?',options:['Viewer coordinates.','Only its sensor packet and private remembered state.','Referee world positions.'],correct:1,explanations:['Viewer truth is not an input to strategy_step.','The current packet has no forward distance return for an opponent behind the robot. The strategy must search or use its own remembered observations.','The world and referee keep truth separate from the brain.']},recap:["The viewer’s world coordinates are not strategy inputs.", "When danger and target appear together, rule order selects the action.", "Repeatable inputs and bounded execution work make strategy comparisons meaningful."],terms:[{term:'Finite-state strategy',meaning:'A small set of behaviours and rules for changing between them.'},{term:'Determinism',meaning:'Identical initial state and inputs produce identical results.'},{term:'Worst-case budget',meaning:'The permitted maximum work for one execution; even the slowest allowed input must fit.'}],sources:[src(18,'Slide.md'),src(18,'Lab.md'),src(18,'strategy.h'),src(18,'student.c'),src(18,'world.c'),src(18,'host/league.c')],limitations:['Reduced single-round browser world; no original tyre/contact dynamics, full sensor noise or tournament outcomes.']},
{id:19,start:{"problem": "A working project needs a complete useful behaviour, resource owners, timing limits and a defined response to failures.", "outcome": "Write one measurable input-to-output outcome, explain each task’s timing, and identify what evidence still requires hardware.", "firstExperiment": ["In Project goal / why it exists, write one behaviour; in Measurable acceptance requirement, specify a number and how you will measure it.", "In Task 1, set budget to 12 ms while keeping deadline and period at 10 ms. Read the timing warning and Estimated processor demand, then restore budget to 1 ms.", "Write a failure and safe response in Task 1 recovery; click Export JSON to save a portable copy of your plan."]},shortTitle:'Planning your own project',subtitle:"Turn a useful behaviour into a design you can measure and explain.",prerequisites:[7,8,11,12,13,16,17,18],youKnow:["Hardware interfaces connect sensor inputs and output commands.", "Scheduled jobs share processor time and sometimes data.", "A simulated result is different evidence from a hardware measurement."],adds:["Resource ownership and task timing estimates", "Health checks based on progress of every required task", "Acceptance requirements and observable tests"],why:'A working demo is not enough if nobody can explain its timing, shared state, failure response or evidence.',topics:[
 topic("Start with one complete, measurable behaviour","Choose a small behaviour that goes all the way from an input to a useful output, such as sensing an obstacle and stopping the wheels. This is a minimum viable product, or MVP. Give it a measurable acceptance requirement: a number and observation that tell you whether the behaviour worked.","A working driver alone does not show the application achieved its purpose. One complete path gives you something to test early.","State the useful behaviour and a numerical success requirement. Identify the sensor or input needed to decide what to do. Pass that input into the application’s step calculation. Send the resulting command to an output such as a motor. Measure the physical result against the requirement and record the evidence.",'Course offers game, drone, robot or approved own-idea tracks. app.c separates state, pure step, draw and framed telemetry; host/test_app.c tests that exact pure C application.','Write a goal and one numeric acceptance criterion in the saved workspace. Trace it through one input and one output.',src(19,'app.h'),["State the useful behaviour and a numerical success requirement.", "Identify the sensor or input needed to decide what to do.", "Pass that input into the application’s step calculation.", "Send the resulting command to an output such as a motor.", "Measure the physical result against the requirement and record the evidence."],"A first project milestone is a complete input-to-result path you can measure."),
 topic("Assign each peripheral an owner and protect shared data","A task is a scheduled job with its own work, such as reading sensors or drawing a display. Give each hardware interface an owner so two tasks do not write conflicting commands. When tasks exchange data, use a complete snapshot or a queue of messages. A mutex grants one task at a time access to a shared resource; a short critical section briefly prevents conflicting access during a copy.","Ownership prevents competing commands, while protection prevents half-updated readings. Both rules must fit the timing needs of the tasks.","List jobs, how often each runs, and the latest time it may finish. Assign one task to issue commands to each peripheral. Choose snapshots or queued messages for information exchanged between tasks. Use a short critical section for nonblocking copies and a mutex when tasks may wait for a shared bus. Specify who consumes remembered button presses and what happens if an owner stops progressing.",'Course template has input, app, display, telem, health and shell tasks. A short nonblocking copy can use a critical section; waits on a bus need a mutex. Sticky button edges need explicit consume semantics.','Add shared data and its protection rule to each task. Follow UART back to lesson 08 and scheduling back to 07.',src(19,'Main.c'),["List jobs, how often each runs, and the latest time it may finish.", "Assign one task to issue commands to each peripheral.", "Choose snapshots or queued messages for information exchanged between tasks.", "Use a short critical section for nonblocking copies and a mutex when tasks may wait for a shared bus.", "Specify who consumes remembered button presses and what happens if an owner stops progressing."],"Resource ownership answers who commands it; data protection answers who can access it together."),
 topic("Separate timing estimates from target measurements","Period is the time between releases of a task. Deadline is the latest permitted finish after release. Budget is the amount of processor time you expect its work to use. Budget divided by period estimates its share of processor time. Add these shares for a first check, then measure on the actual microcontroller and include waiting and interruptions.","An estimate helps catch an impossible plan early, but a fast desktop test cannot establish a hardware deadline or memory limit.","Assign each task a period, deadline and estimated execution budget. Divide budget by period and add task shares to estimate processor demand. Measure execution and response times on the target, including delays from shared resources. Inspect stack usage and the linker’s memory report to check RAM and program storage. Compare measured evidence with requirements; account for timer wrap and unobserved worst cases.",'Course STM32C031C6 has 32 KB Flash and 12 KB SRAM. prof.c uses TIM14 at 1 MHz assuming 48 MHz timer input, wraps at 65,536 µs. One-wrap subtraction cannot measure arbitrary long calls. CPU tick sampling can miss short tasks.','Make an estimated budget exceed its deadline and read the warning. Record how you will obtain a target measurement.',src(19,'prof.c'),["Assign each task a period, deadline and estimated execution budget.", "Divide budget by period and add task shares to estimate processor demand.", "Measure execution and response times on the target, including delays from shared resources.", "Inspect stack usage and the linker’s memory report to check RAM and program storage.", "Compare measured evidence with requirements; account for timer wrap and unobserved worst cases."],"Budget predicts work; a target measurement supplies evidence. Neither alone proves every deadline."),
 topic("Feed the watchdog only after all required jobs progress","A watchdog is a timer that resets the processor unless software regularly refreshes it. A heartbeat counter advances when a required task makes useful progress. The health task compares all required counters with their previous values and refreshes the watchdog only if all advanced. Otherwise a frozen task should lead to the specified reset or safe response.","One active task can keep an unhealthy system alive if it refreshes the watchdog without checking the other jobs.","Each required task increments its heartbeat after useful work. The health task compares each counter with the value saved at the last check. If every required task advanced, refresh the independent watchdog timer. If a required counter did not advance, withhold refresh and report the missing progress. A hardware watchdog can reset even if the CPU stops scheduling; the course’s software simulator fallback cannot handle every CPU-starving loop.",'Course health check runs every 250 ms; IWDG nominal timeout ~1 s from ~32 kHz LSI /32 and RLR=999. Oscillator tolerance matters. Wokwi C031 IWDG is unsupported; course uses a 1500 ms software fallback that cannot rescue a CPU-starving high-priority spin.','For each task write a failure and safe recovery. Contrast blocked task versus highest-priority infinite loop.',src(19,'health.c'),["Each required task increments its heartbeat after useful work.", "The health task compares each counter with the value saved at the last check.", "If every required task advanced, refresh the independent watchdog timer.", "If a required counter did not advance, withhold refresh and report the missing progress.", "A hardware watchdog can reset even if the CPU stops scheduling; the course’s software simulator fallback cannot handle every CPU-starving loop."],"Refresh the watchdog for useful progress by all required tasks, not merely any running code.",'if (b == h->prev[i]) { missing |= 1u << i; }\nh->prev[i] = b;'),
 topic("Match each project claim to observable evidence","A test plan connects each requirement to inputs, expected results, and a way to observe them. A host test runs pure application logic on a computer. A simulation checks how parts work together in a model. Hardware measurements support claims about the actual device. Fault injection means deliberately causing a defined failure to check the promised recovery.","A successful demonstration proves one observed run. Boundary cases, long runs, timing measurements and controlled failures support broader claims.","Write one requirement and the observation that would satisfy it. Test ordinary inputs and values at the permitted boundaries. Run long enough to expose accumulating errors or resource use. Inject a defined failure after specifying a safe recovery. Record the result, measurement method and limits of the evidence; disclose and understand AI-assisted code.",'Course six-week milestones: proposal, design review, build, mid demo, measure, final. Rubric rewards working system, argued architecture, measured requirements, host tests and demonstrated fault response. AI assistance must be disclosed and understood.','Add a test and measurement method to the workspace. Explain one code line and the physical result it should cause.',src(19,'Lab.md'),["Write one requirement and the observation that would satisfy it.", "Test ordinary inputs and values at the permitted boundaries.", "Run long enough to expose accumulating errors or resource use.", "Inject a defined failure after specifying a safe recovery.", "Record the result, measurement method and limits of the evidence; disclose and understand AI-assisted code."],"Every acceptance claim needs a named test and evidence from the kind of system being claimed.")],prediction:{question:'The display task freezes, but the app keeps feeding IWDG. Is this a sound health policy?',options:['Yes, some software is alive.','No, feed only if all required heartbeats advanced.','Yes, the display is slow anyway.'],correct:1,explanations:['Activity does not establish that every required function works.','If the display is required, its frozen heartbeat must prevent watchdog refresh even while the app runs. The health check requires every required task to advance.','A deadline and failure policy must define whether the display is required.']},recap:["Start with one complete useful input-to-output behaviour.", "Assign resource owners and protect complete shared updates.", "Label budgets as estimates, then collect target evidence for timing and memory.", "Specify a safe response before deliberately causing a fault."],terms:[{term:'MVP',meaning:'Minimum viable product: the smallest complete useful outcome.'},{term:'Heartbeat',meaning:'A counter advanced when a required task makes useful progress.'},{term:'Period / deadline / budget',meaning:'Period: time between job releases. Deadline: latest permitted finish after release. Budget: processor time allotted or estimated for its work.'}],sources:[src(19,'Slide.md'),src(19,'Lab.md'),src(19,'app.c'),src(19,'health.c'),src(19,'prof.c'),src(19,'host/test_app.c')],limitations:['Workspace estimates utilization; it does not prove schedulability, measure MCU cycles or generate firmware.','Saved locally in this browser; export JSON for a portable backup.']}
];
export default applications;

